{"command":"node -e "
const { respondFiber, kJoin, toBil } = require('./operations/engineering/fars/agentic/tools/respond.js');
const { T, BOT, TOP, F, name, equals } = require('./operations/engineering/fars/agentic/tools/predication.js');

console.log('=== Navigation as fiber composition ===');
console.log();

// The room's fiber includes exit predicates and the room's own identity
const room = new Map([
  ['exit-north:north-of-house', T],
  ['exit-south:south-of-house', T],
  ['exit-east:boarded', F],
  ['description:West of House', T],
]);

// The message: player wants to go north
// What does this message ASSERT? It asserts 'direction:north = t'
const goNorth = new Map([
  ['direction:north', T],
]);

// respond(room, goNorth)
const r1 = respondFiber(room, goNorth);
console.log('respond(room, {direction: north}):');
console.log('  contested:', r1.contested);
console.log('  delta:', r1.delta);
console.log('  Result has exit-north?', name(r1.result.get('exit-north:north-of-house')));
console.log();

// Hmm — the message says nothing about exits, so no contestation.
// The result is just the room's fiber plus direction:north = t.
// That's a query, not a state change. Correct.

// The room RESPONDED with its fiber. The caller reads exit-north
// from the response. But that's JS reading, not algebra composing.

console.log('=== Alternative: the exit IS the message ===');
console.log();

// What if we encode the room differently?
// Instead of exit predicates being data TO READ,
// they're RESPONSE predicates — what the room asserts ABOUT the direction.
// The room's fiber for direction:north IS the destination.

// Room fiber: when asked about north, I answer north-of-house
const room2 = new Map([
  ['north:destination', T],           // north has a destination
  ['north:north-of-house', T],        // that destination is north-of-house
  ['south:destination', T],
  ['south:south-of-house', T],
  ['east:blocked', T],
  ['east:message', T],
]);

// The player's fiber: I am at west-of-house
const player = new Map([
  ['at:west-of-house', T],
  ['at:north-of-house', F],           // I am NOT at north-of-house
]);

// The GO NORTH action: I want to be at wherever north leads
// Constructed from the room's north:north-of-house predicate
const moveNorth = new Map([
  ['at:west-of-house', F],             // deny current location
  ['at:north-of-house', T],            // affirm new location
]);

const r2 = respondFiber(player, moveNorth);
console.log('respond(player, {at:west-of-house=f, at:north-of-house=t}):');
console.log('  contested:', r2.contested);
for (const [k, v] of Object.entries(r2.delta)) console.log('  ' + k + ': ' + v.from + ' → ' + v.to);
console.log();
console.log('Player moved! at:west-of-house went t→f, at:north-of-house went f→t.');
console.log('Both passed through ⊤.');
console.log();

console.log('=== The deep question: can the ROOM construct the movement message? ===');
console.log();

// What if we compose the player's GO-NORTH intent with the room's fiber?
// The player says: I want to go north.
// The room says: north leads to north-of-house.
// The COMPOSITION should produce the movement message.

// Player intent: go north = {intent:go = t, intent:north = t}
const intent = new Map([
  ['intent:go', T],
  ['intent:north', T],
]);

// Room knowledge: north → north-of-house
const roomKnowledge = new Map([
  ['north:north-of-house', T],
  ['north:destination', T],
]);

// Compose: intent ∨_k room-knowledge
const composed = new Map();
const allKeys = new Set([...intent.keys(), ...roomKnowledge.keys()]);
for (const k of allKeys) {
  composed.set(k, kJoin(intent.get(k) || BOT, roomKnowledge.get(k) || BOT));
}
console.log('intent ∨_k room-knowledge:');
for (const [k, v] of composed) console.log('  ' + k + ' = ' + name(v));

console.log();
console.log('No contestation — intent and room agree (no overlapping propositions).');
console.log('The composed fiber has BOTH the intent AND the destination.');
console.log('The next step: the player reads north:north-of-house from the');
console.log('composed fiber and constructs the movement message.');
console.log();
console.log('But that reading is still JS. The algebra composed the information,');
console.log('but it did not PRODUCE the movement message automatically.');
console.log();
console.log('Unless... the player\\'s fiber encodes HOW TO MOVE.');
"","description":"Explore navigation as pure fiber composition"}

