{"command":"node -e "
const { respondFiber, kJoin } = require('./operations/engineering/fars/agentic/tools/respond.js');
const { T, BOT, TOP, F, name, equals } = require('./operations/engineering/fars/agentic/tools/predication.js');

console.log('=== The fiber functor morphism as navigation ===');
console.log();
console.log('The paper (Section 3.2) defines three classes of morphisms:');
console.log('  1. Specialization: restrict valuations');
console.log('  2. Inversion: apply negation ~ pointwise');
console.log('  3. Composition: apply ∧_k pointwise');
console.log();
console.log('Navigation is a COMPOSITION morphism.');
console.log();
console.log('The exit predicate \"exit-north\" and the location predicate \"at\"');
console.log('are related by composition: exit-north(room, destination) composed');
console.log('with at(player, room) yields at(player, destination).');
console.log();
console.log('In the functor: Fib(exit-north) → Fib(at) is a bilattice homomorphism.');
console.log('It maps the room\\'s exit value to the player\\'s location value.');
console.log();
console.log('Concretely:');
console.log('  room has exit-north:north-of-house = t');
console.log('  player has at:west-of-house = t');
console.log('  The morphism maps (exit-north = t) to (at:destination = t, at:current = f)');
console.log();
console.log('This IS ∧_k applied to the relevant fibers:');

// The morphism: compose exit-value with direction-value via ∧_k
// exit-north:north-of-house = t (room says north leads there)
// direction:north = t (player wants to go north)
// ∧_k(t, t) = t (composition: both agree → the navigation holds)

const exitVal = T;     // exit-north = t
const dirVal = T;      // direction:north = t
const composed = [Math.min(exitVal[0], dirVal[0]), Math.min(exitVal[1], dirVal[1])];
console.log();
console.log('exit-north = t, direction:north = t');
console.log('∧_k(t, t) = ' + name(composed) + ' → navigation IS valid');
console.log();

// What if exit is blocked?
const blockedExit = F;  // exit-east = f
const compBlocked = [Math.min(blockedExit[0], dirVal[0]), Math.min(blockedExit[1], dirVal[1])];
console.log('exit-east = f, direction:east = t');
console.log('∧_k(f, t) = ' + name(compBlocked) + ' → navigation is BLOCKED');
console.log();

// What if exit is conditional?
const condExit = BOT;   // exit-sw = ⊥
const compCond = [Math.min(condExit[0], dirVal[0]), Math.min(condExit[1], dirVal[1])];
console.log('exit-sw = ⊥, direction:sw = t');
console.log('∧_k(⊥, t) = ' + name(compCond) + ' → navigation is UNKNOWN');
console.log();

console.log('=== THE RESULT ===');
console.log();
console.log('Navigation validity = ∧_k(exit-value, direction-value)');
console.log('  t → valid, proceed with location change');
console.log('  f → blocked, return failure message');
console.log('  ⊥ → conditional not met, return failure');
console.log('  ⊤ → contested (shouldn\\'t happen for exits)');
console.log();
console.log('The navigation CHECK is algebraic: ∧_k on two fibers.');
console.log('The navigation ACTION is algebraic: respond(player, movement-fiber).');
console.log('The only JS needed: the cascade that connects the check to the action.');
console.log();
console.log('And the cascade IS the functor morphism.');
console.log('It\\'s the bilattice homomorphism from Fib(exit) to Fib(at).');
console.log('The functor DEFINES it. We just need to execute it.');
console.log();
console.log('=== Perception is the same pattern ===');
console.log();
console.log('Perceive(room) = compose room fiber with all contained object fibers.');
console.log('The composition morphism: Fib(contains) → Fib(visible).');
console.log('room has contains:sword = t. sword has description:\"elvish sword\" = t.');
console.log('The morphism maps (contains = t) to (visible:description = t).');
console.log('That\\'s ∧_k again: ∧_k(contains:sword, sword:description) = t.');
console.log('The t-valued descriptions in the composed fiber ARE the room description.');
"","description":"Work out navigation and perception as functor morphisms"}

