 * state predicates, add edge predicates, mark objects.
 *
 * The player IS an entity. It has synonyms, a location, and a fiber.
 * It responds to messages the same way everything else does.
 */
function initWorld(world) {
  // The player entity
  world.player = {
    id: "player",
    fiber: new Map([
      ["location:west-of-house", T],
      ["alive:true", T],
      ["score:0", T],
      ["synonym:me", T],
      ["synonym:self", T],
      ["synonym:myself", T],
      ["synonym:player", T],
      ["description-short:yourself", T],
      ["type:actor", T],
