    meta: {
      type: "actor",
      descriptions: { short: "yourself" },
      synonyms: ["me", "self", "myself", "player"],
      adjectives: [],
    },
  };

  // Helper: set a predicate if not already present
  function init(id, prop, val) {
    const ent = world[id];
    if (ent && !ent.fiber.has(prop)) ent.fiber.set(prop, val);
  }

  // Container/door initial states
  init("mailbox", "state:open", F);
  init("mailbox", "state:closed", T);
  init("kitchen-window", "state:open", F);
  init("kitchen-window", "state:closed", T);

  // Edge predicates: kitchen-window → room exits
  const kw = world["kitchen-window"];
  if (kw) {
    kw.fiber.set("edge:state:open:t:east-of-house:exit-west:kitchen", T);
    kw.fiber.set("edge:state:open:t:east-of-house:exit-in:kitchen", T);
    kw.fiber.set("edge:state:open:t:kitchen:exit-out:east-of-house", T);
    kw.fiber.set("edge:state:open:t:kitchen:exit-east:east-of-house", T);
  }

  // Mark all objects with state:here/held based on location
  for (const [id, ent] of Object.entries(world)) {
    if (ent.meta?.type !== "object") continue;
    for (const [key, val] of ent.fiber) {
      if (key.startsWith("location:") && equals(val, T)) {
        ent.fiber.set("state:here", T);
        ent.fiber.set("state:held", F);
        break;
      }
    }
  }

