{"file_path":"/home/emsenn/561/operations/science/research/predicated-zork/play.js","content":"#!/usr/bin/env node
/**
 * play.js — Play predicated Zork.
 *
 * The thinnest possible shell: read text → respond() → print text.
 * All game logic is in the algebra (∨_k/⊙/∧_k on entity fibers).
 * The player is an entity in the world, not a special JS object.
 *
 * Run: node operations/science/research/predicated-zork/play.js
 */
"use strict";

const readline = require("readline");
const path = require("path");
const alg = require("./algebraic-engine.js");

// ── Load and initialize world ─────────────────────────────────────

const world = alg.loadWorld(path.join(__dirname, "zork-world-generated.json"));
const player = alg.initWorld(world);

// ── Helpers (delegated to engine's algebra) ───────────────────────

function getPlayerRoom() {
  const loc = alg.fiberQuery(player.fiber, "location").find(([, v]) => alg.equals(v, alg.T));
  return loc ? loc[0] : null;
}

function resolveNoun(word) {
  return alg.resolveSynonym(world, word, player.fiber);
}

// ── Parse ─────────────────────────────────────────────────────────

const DIRS = {
  n: "north", s: "south", e: "east", w: "west", u: "up", d: "down",
  north: "north", south: "south", east: "east", west: "west",
  up: "up", down: "down", ne: "ne", nw: "nw", se: "se", sw: "sw",
  in: "in", out: "out", enter: "in", exit: "out",
};

const VERBS = {
  l: "look", look: "look", x: "examine", examine: "examine",
  read: "read", take: "take", get: "take", drop: "drop",
  open: "open", close: "close", shut: "close",
  i: "inventory", inventory: "inventory",
  kill: "attack", attack: "attack", fight: "attack",
  move: "move", push: "move", pull: "move",
  q: "quit", quit: "quit",
};

function parse(line) {
  const raw = line.trim().toLowerCase();
  if (!raw) return null;
  if (raw === "q" || raw === "quit") return { verb: "quit" };
  if (DIRS[raw]) return { verb: "go", direction: DIRS[raw] };

  if (raw.startsWith("go ")) {
    const d = DIRS[raw.slice(3).trim()];
    if (d) return { verb: "go", direction: d };
  }

  if (raw.startsWith("turn on ")) return { verb: "turn-on", target: resolveNoun(raw.slice(8).trim()) };
  if (raw.startsWith("turn off ")) return { verb: "turn-off", target: resolveNoun(raw.slice(9).trim()) };
  if (raw.startsWith("look in ")) return { verb: "look-inside", target: resolveNoun(raw.slice(8).trim()) };

  const words = raw.split(/\s+/);
  const verb = VERBS[words[0]];
  if (!verb) {
    if (DIRS[words[0]]) return { verb: "go", direction: DIRS[words[0]] };
    return null;
  }
  if (verb === "look" && words.length === 1) return { verb: "look" };
  if (verb === "inventory") return { verb: "inventory" };

  const rest = words.slice(1).filter(w => !["the", "a", "an"].includes(w));
  const withIdx = rest.indexOf("with");
  const objWords = withIdx >= 0 ? rest.slice(0, withIdx) : rest;
  const indWords = withIdx >= 0 ? rest.slice(withIdx + 1) : [];

  return {
    verb,
    target: resolveNoun(objWords.join(" ")),
    indirect: resolveNoun(indWords.join(" ")),
  };
}

// ── Turn loop ─────────────────────────────────────────────────────

const rl = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "\n> " });

console.log("ZORK I: The Great Underground Empire");
console.log("(Predicated Zork — running on ∨_k/⊙/∧_k, zero rules)\n");
console.log(alg.perceive(world, getPlayerRoom()));

rl.prompt();

rl.on("line", (line) => {
  const parsed = parse(line);
  if (!parsed) { console.log("I don't understand that."); rl.prompt(); return; }
  if (parsed.verb === "quit") { console.log("Goodbye."); process.exit(0); }

  const result = alg.act(world, player, parsed.verb, parsed.target, parsed.direction);
  if (result.text) console.log(result.text);
  rl.prompt();
});

rl.on("close", () => { console.log("\nGoodbye."); process.exit(0); });
"}

