    in: "in", out: "out", enter: "in", exit: "out",
  };
  for (const [syn, canonical] of Object.entries(dirMap)) {
    vocabFiber.set("direction:" + syn + ":" + canonical, T);
  }

  // Prepositions that split direct/indirect objects
  for (const prep of ["with", "in", "to", "on", "at"]) {
    vocabFiber.set("preposition:" + prep, T);
  }

  // Buzz words to filter
  for (const buzz of ["the", "a", "an"]) {
    vocabFiber.set("buzz:" + buzz, T);
  }

  // Multi-word verb phrases
  vocabFiber.set("phrase:turn on:turn-on", T);
  vocabFiber.set("phrase:turn off:turn-off", T);
  vocabFiber.set("phrase:look in:look-inside", T);
  vocabFiber.set("phrase:look inside:look-inside", T);
