/**
 * Parse input text using the vocabulary entity's fiber.
 * All lookups are ∧_k on vocabulary predicates.
 */
function parseInput(world, text, playerFiber) {
  const vocab = world.vocabulary;
  if (!vocab) return null;

  const raw = text.trim().toLowerCase();
  if (!raw) return null;

  // Check multi-word phrases first
  const phrases = fiberQuery(vocab.fiber, "phrase");
  for (const [phraseSpec, val] of phrases) {
    if (!equals(kMeet(val, T), T)) continue;
    const parts = phraseSpec.split(":");
    const phrase = parts[0];
    const canonical = parts[1];
    if (raw.startsWith(phrase + " ")) {
      const rest = raw.slice(phrase.length + 1).trim();
      const target = resolveSynonym(world, rest, playerFiber);
      return { verb: canonical, target };
