"use strict";

const fs = require("fs");
const path = require("path");

const REPO_ROOT = (() => {
  let dir = __dirname;
  while (dir !== "/" && !fs.existsSync(path.join(dir, "knowledge-graph.json"))) {
    dir = path.dirname(dir);
  }
  return dir;
})();

const OBS_DIR = path.join(REPO_ROOT, "operations/engineering/records/observations");
const OBS_FILE = path.join(OBS_DIR, "observations.jsonl");
const INSTINCTS_DIR = path.join(REPO_ROOT, "operations/engineering/records/instincts/personal");
const EVENTS_FILE = path.join(REPO_ROOT, "operations/engineering/records/events/events.jsonl");

const DEFAULT_MIN_COUNT = 3;
const MAX_OBS_LINES = 2000;

/**
 * Read recent observations from the JSONL file.
 */
function readObservations(maxLines) {
  if (!fs.existsSync(OBS_FILE)) return [];
  const content = fs.readFileSync(OBS_FILE, "utf8");
  const lines = content.split("\n").filter(l => l.trim());
  const recent = lines.slice(-maxLines);
  const obs = [];
  for (const line of recent) {
    try { obs.push(JSON.parse(line)); }
    catch { /* skip malformed */ }
  }
  return obs;
}

/**
 * Read existing instinct IDs to avoid duplicates.
 */
function existingInstincts() {
  if (!fs.existsSync(INSTINCTS_DIR)) return new Set();
  return new Set(
    fs.readdirSync(INSTINCTS_DIR)
      .filter(f => f.endsWith(".md"))
      .map(f => f.replace(/\.md$/, ""))
  );
}

/**
 * Detect tool-pair sequences: tool A followed by tool B in the same session.
 * Returns array of { pair: [A, B], count, sessions }.
 */
function detectToolPairs(observations, minCount) {
  const pairs = new Map(); // "A→B" → { count, sessions: Set }

