  const bySession = new Map();
  for (const obs of observations) {
    if (obs.event !== "tool_start") continue;
    const sid = obs.session || "unknown";
    if (!bySession.has(sid)) bySession.set(sid, []);
    bySession.get(sid).push(obs.tool);
  }

  for (const [sid, tools] of bySession) {
    for (let i = 0; i < tools.length - 1; i++) {
      const pair = `${tools[i]}→${tools[i + 1]}`;
      if (!pairs.has(pair)) pairs.set(pair, { count: 0, sessions: new Set() });
      const p = pairs.get(pair);
      p.count++;
      p.sessions.add(sid);
    }
  }

  return [...pairs.entries()]
    .filter(([, v]) => v.count >= minCount)
    .map(([pair, v]) => ({
      pair: pair.split("→"),
      count: v.count,
      sessions: v.sessions.size,
    }))
    .sort((a, b) => b.count - a.count);
}

/**
 * Detect tools that consistently precede another tool (>80% of the time).
 * This captures patterns like "always Grep before Edit".
 */
