  const follows = new Map(); // tool → Map<predecessor, count>
  const toolCounts = new Map(); // tool → total occurrences

  const bySession = new Map();
  for (const obs of observations) {
    if (obs.event !== "tool_start") continue;
    const sid = obs.session || "unknown";
    if (!bySession.has(sid)) bySession.set(sid, []);
    bySession.get(sid).push(obs.tool);
  }

  for (const [, tools] of bySession) {
    for (let i = 0; i < tools.length; i++) {
      const tool = tools[i];
      toolCounts.set(tool, (toolCounts.get(tool) || 0) + 1);
