{"file_path":"/home/emsenn/561/operations/science/research/predicated-zork/algebraic-engine.js","content":"#!/usr/bin/env node
/**
 * algebraic-engine.js — Zork on three operations.
 *
 * ∨_k — introduce contestation where entity and message disagree
 * ⊙   — resolve contestation using evidence
 * ∧_k — compose across predicates (navigation, perception, dispatch)
 *
 * Verbs, the player, the vocabulary — all entities with fibers.
 * act() is two respond() calls: verb produces action, target receives it.
 */
"use strict";

const fs = require("fs");
const path = require("path");
const { respondFiber, toBil } = require(
  path.resolve(__dirname, "../../../engineering/fars/agentic/tools/respond.js")
);
const { extend, T, BOT, TOP, F, name, equals, kJoin, kMeet } = require(
  path.resolve(__dirname, "../../../engineering/fars/agentic/tools/predication.js")
);

// ── Fiber helpers ─────────────────────────────────────────────────

function fiberQuery(fiber, prefix) {
  const results = [];
  for (const [key, val] of fiber) {
    if (key.startsWith(prefix + ":"))
      results.push([key.slice(prefix.length + 1), val]);
  }
  return results;
}

function fiberDesc(ent, predicate) {
  if (!ent?.fiber) return null;
  for (const [text, bil] of fiberQuery(ent.fiber, predicate)) {
    if (equals(bil, T)) return text;
  }
  return null;
}

function describeShort(world, id) {
  return fiberDesc(world[id], "description-short") || id;
}

function playerRoom(playerFiber) {
  const loc = fiberQuery(playerFiber, "location").find(([, v]) => equals(v, T));
  return loc ? loc[0] : null;
}

function delta(before, after) {
  const changes = [];
  for (const key of new Set([...before.keys(), ...after.keys()])) {
    const b = before.get(key) || BOT;
    const a = after.get(key) || BOT;
    if (!equals(b, a)) changes.push({ key, from: name(b), to: name(a) });
  }
  return changes;
}

// ── World loading ─────────────────────────────────────────────────

function loadWorld(filePath) {
  const raw = JSON.parse(fs.readFileSync(filePath, "utf8"));
  const world = {};
  for (const [id, ent] of Object.entries(raw.entities)) {
    const fiber = new Map();
    if (ent.type) fiber.set("type:" + ent.type, T);
    for (const [pred, val, bil] of ent.fiber) fiber.set(pred + ":" + val, toBil(bil));
    world[id] = { id, fiber };
  }
  return world;
}

// ── Perception ────────────────────────────────────────────────────
// ∧_k on location predicates determines visibility.

function perceive(world, roomId) {
  const room = world[roomId];
  if (!room) return "You are nowhere.";
  const parts = [];

  const shortDesc = fiberDesc(room, "description-short");
  if (shortDesc) parts.push(shortDesc);

  const longDesc = fiberDesc(room, "description-long");
  const visited = room.fiber.has("visited:true") && equals(room.fiber.get("visited:true"), T);
  if (longDesc && !visited) { parts.push(longDesc); room.fiber.set("visited:true", T); }

  for (const [id, ent] of Object.entries(world)) {
    if (!ent.fiber.has("type:object")) continue;
    if (!equals(kMeet(ent.fiber.get("location:" + roomId) || BOT, T), T)) continue;
    if (equals(kMeet(ent.fiber.get("no-describe:true") || BOT, T), T)) continue;

    const touched = ent.fiber.has("touched:true") && equals(ent.fiber.get("touched:true"), T);
    const first = fiberDesc(ent, "description-first");
    const later = fiberDesc(ent, "description-long");
    const desc = fiberDesc(ent, "description-short");

    if (first && !touched) parts.push(first);
    else if (later) parts.push(later);
    else if (desc) parts.push("There is a " + desc + " here.");
  }
  return parts.join("\n");
}

// ── Edge propagation ──────────────────────────────────────────────
// Edges are predicates: edge:{changed}:{new-val}:{target}:{pred}:{val} = t

function propagateEdges(world, entityId, changes) {
  const ent = world[entityId];
  if (!ent) return;
  for (const change of changes) {
    const prefix = "edge:" + change.key + ":" + change.to + ":";
    for (const [key, val] of ent.fiber) {
      if (!key.startsWith(prefix) || !equals(kMeet(val, T), T)) continue;
      const rest = key.slice(prefix.length);
      const sep = rest.indexOf(":");
      if (sep < 0) continue;
      const targetId = rest.slice(0, sep);
      const targetProp = rest.slice(sep + 1);
      const target = world[targetId];
      if (!target) continue;
      const { result } = respondFiber(target.fiber, new Map([[targetProp, T]]));
      target.fiber = result;
    }
  }
