/**
 * algebraic-engine.js — Zork on ∨_k, ⊙, ∧_k. Nothing else.
 *
 * The engine is: respond(target, verb-fiber) → propagate edges → assemble text.
 * Node.js handles readline and string joining. Everything else is algebra.
 *
 * ⊥ is null. Type entities are inheritance. Edges are dispatch.
 */
"use strict";

const fs = require("fs");
const path = require("path");
const { respondFiber, toBil } = require(
  path.resolve(__dirname, "../../../engineering/fars/agentic/tools/respond.js")
);
const { extend, T, BOT, TOP, F, name, equals, kJoin, kMeet } = require(
  path.resolve(__dirname, "../../../engineering/fars/agentic/tools/predication.js")
);

// ── Fiber primitives ──────────────────────────────────────────────
// These are the ONLY non-algebraic functions: iteration over Map entries.
// They read results. They don't compute them.

const EMPTY_FIBER = new Map();

function fq(fiber, prefix) {
  const r = [];
  if (!fiber) return r;
  for (const [k, v] of fiber) if (k.startsWith(prefix + ":")) r.push([k.slice(prefix.length + 1), v]);
  return r;
}

function fd(ent, pred) {
  if (!ent) return null;
  const fiber = ent.fiber || ent;
  for (const [t, b] of fq(fiber, pred)) if (equals(b, T)) return t;
  return null;
}

function pr(fiber) {
  if (!fiber) return null;
  const loc = fq(fiber, "location").find(([, v]) => equals(v, T));
  return loc ? loc[0] : null;
}

function is(fiber, key) { return fiber ? equals(kMeet(fiber.get(key) || BOT, T), T) : false; }

function delta(a, b) {
  const d = [];
  const ak = a || EMPTY_FIBER, bk = b || EMPTY_FIBER;
  for (const k of new Set([...ak.keys(), ...bk.keys()])) {
    const x = ak.get(k) || BOT, y = bk.get(k) || BOT;
    if (!equals(x, y)) d.push({ key: k, from: name(x), to: name(y) });
  }
  return d;
}

// ── Load ──────────────────────────────────────────────────────────

function loadWorld(fp) {
  const raw = JSON.parse(fs.readFileSync(fp, "utf8"));
  const w = {};
  for (const [id, ent] of Object.entries(raw.entities)) {
    const f = new Map();
    if (ent.type) f.set("type:" + ent.type, T);
    for (const [p, v, b] of ent.fiber) f.set(p + ":" + v, toBil(b));
    w[id] = { id, fiber: f };
  }
  return w;
}

// ── The primitive: respond + propagate ─────────────────────────────

/**
 * Send a message (fiber) to a target entity. Merge via ∨_k, settle via ⊙.
 * Then propagate: for each changed proposition, fire matching edge predicates.
 * Edges send messages to other entities — the tick cascading through the graph.
 *
 * Returns { changes, contested, text-parts }.
 */
function send(world, targetId, msgFiber) {
  const ent = world[targetId];
  // ⊥ IS null: non-existent entity produces empty response, no crash
  const entFiber = ent ? ent.fiber : EMPTY_FIBER;
  const before = new Map(entFiber);

  const { result, contested } = respondFiber(entFiber, msgFiber);
  if (ent) ent.fiber = result;

  const changes = delta(before, result);

  // Propagate edges: edge:{changed-prop}:{new-val}:{target}:{prop} = t
  for (const c of changes) {
    const pfx = "edge:" + c.key + ":" + c.to + ":";
    for (const [k, v] of result) {
      if (!k.startsWith(pfx) || !equals(kMeet(v, T), T)) continue;
      const rest = k.slice(pfx.length), sep = rest.indexOf(":");
      if (sep < 0) continue;
      const tid = rest.slice(0, sep), tprop = rest.slice(sep + 1);
      const target = world[tid];
      if (target) target.fiber = respondFiber(target.fiber, new Map([[tprop, T]])).result;
    }
  }

  return { changes, contested };
}

// ── Perceive ──────────────────────────────────────────────────────
// Read t-valued description predicates from room + visible objects.
// The visibility check is ∧_k. The assembly is string joining.

function perceive(world, roomId) {
  const room = world[roomId];
  const parts = [];

  // Room description — from fiber, ⊥ if no room
  const sd = fd(room, "description-short");
  if (sd) parts.push(sd);

  const ld = fd(room, "description-long");
  const vis = room ? is(room.fiber, "visited:true") : true;
  if (ld && !vis) { parts.push(ld); room.fiber.set("visited:true", T); }

  // Visible objects: ∧_k(location:{roomId}, t) on each entity
  for (const [id, ent] of Object.entries(world)) {
    if (!is(ent.fiber, "type:object")) continue;
    if (!is(ent.fiber, "location:" + roomId)) continue;
    if (is(ent.fiber, "no-describe:true")) continue;

    const touched = is(ent.fiber, "touched:true");
    const f = fd(ent, "description-first"), l = fd(ent, "description-long"), s = fd(ent, "description-short");
    parts.push(f && !touched ? f : l || (s ? "There is a " + s + " here." : null));
  }
  return parts.filter(Boolean).join("\n") || "";
}

